ALTER TABLE enquiries ADD COLUMN enquiry_type ENUM('general','bulk') NOT NULL DEFAULT 'general' AFTER id, ADD COLUMN company_name VARCHAR(180) NULL AFTER name, ADD COLUMN address TEXT NULL AFTER company_name, ADD COLUMN employee_size VARCHAR(80) NULL AFTER address, ADD COLUMN combo_boxes_required VARCHAR(80) NULL AFTER message, ADD COLUMN custom_quantity INT UNSIGNED NULL AFTER combo_boxes_required;
